#!/usr/bin/env node
/**
 * Agent Pilot - Embed skills into the Go CLI as base64 assets.
 * Generates cli/skill_assets.go (committed) so a standalone `go build` works
 * without the repository sources present.
 *
 * Usage:
 *   node scripts/embed_skills.mjs           # regenerate cli/skill_assets.go
 *   node scripts/embed_skills.mjs --check   # exit 1 if the generated file is stale
 */
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = path.resolve(__dirname, "..");
const SKILL_DIR = path.join(ROOT_DIR, "skills", "agent-pilot");
const OUT_FILE = path.join(ROOT_DIR, "cli", "skill_assets.go");

function walk(dir, base = "") {
  const entries = fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name));
  const files = [];
  for (const entry of entries) {
    const rel = base ? `${base}/${entry.name}` : entry.name;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walk(full, rel));
    } else if (entry.isFile()) {
      files.push(rel);
    }
  }
  return files;
}

function generate() {
  if (!fs.existsSync(SKILL_DIR)) {
    throw new Error(`Skill directory not found: ${SKILL_DIR}`);
  }
  const files = walk(SKILL_DIR);
  const lines = [
    "// Code generated by scripts/embed_skills.mjs; DO NOT EDIT.",
    "// Source of truth: skills/agent-pilot/ (run: npm run sync:skills)",
    "",
    "package main",
    "",
    "// embeddedSkillFilesBase64 maps skill-relative paths to base64-encoded contents.",
    "var embeddedSkillFilesBase64 = map[string]string{"
  ];
  for (const rel of files) {
    const data = fs.readFileSync(path.join(SKILL_DIR, rel));
    lines.push(`\t${JSON.stringify(rel)}: ${JSON.stringify(data.toString("base64"))},`);
  }
  lines.push("}");
  lines.push("");
  return { content: formatGo(lines.join("\n")), count: files.length };
}

function formatGo(content) {
  try {
    return execFileSync("gofmt", { input: content, encoding: "utf8" });
  } catch {
    return content.endsWith("\n") ? content : content + "\n";
  }
}

const checkMode = process.argv.includes("--check");
const { content, count } = generate();

if (checkMode) {
  const existing = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, "utf8") : "";
  if (existing !== content) {
    console.error("❌ cli/skill_assets.go is out of date. Run: npm run sync:skills");
    process.exit(1);
  }
  console.log(`✅ cli/skill_assets.go is up to date (${count} skill files)`);
  process.exit(0);
}

fs.writeFileSync(OUT_FILE, content);
console.log(`✅ Embedded ${count} skill files -> cli/skill_assets.go`);
